class Book:
    def __init__(self, title, price):
        self.title = title
        self.price = price
    def show(self):
        print(self.title, self.price)

try:
    title = input()
    price = int(input())
    book = Book(title, price)
    book.show()
except ValueError:
    # 안내 문구를 출력하세요.
    pass
